"""Record the disposition of every legacy Word comment and tracked element."""
from pathlib import Path
from collections import Counter
import json,re

ROOT=Path(__file__).resolve().parents[2]
HERE=Path(__file__).resolve().parent
BASE=ROOT/'ACKSII/База перевода'

def main():
    us=[json.loads(s) for s in (BASE/'units.jsonl').read_text('utf-8').splitlines()]
    byid={u['id']:u for u in us}
    comments=json.loads((HERE/'legacy_comments.json').read_text('utf-8'))
    tracked=json.loads((HERE/'tracked_changes.json').read_text('utf-8'))
    groups=[]
    def find(ch,term,prefix=''):
        ids=[u['id'] for u in us if (ch is None or u['chapter_id']==ch) and term.lower() in re.sub(r'\s+',' ',u['english'].replace('*','')).lower() and u['id'].startswith(prefix)]
        assert ids,(ch,term,prefix)
        return ids
    def group(keys,title,ids,decision,state='учтено'):
        for uid in ids:assert uid in byid,uid
        groups.append({'comments':list(keys),'subject':title,'current_units':ids,'state':state,'decision':decision})
