    group([86],'Evade',['rr.p0336.t01.r011.c04'],'Использовано Избегание [evade], а не боевое уклонение; бонус +4 сохранён.')
    group([87],'Clanholds',find('08','clanholds','rr.p0336'),'Сохранены клановые владения [Clanholds] с текущей ссылкой, без подмены родовым названием персонажей.')
