    group([103,104,105],'Medicine Lodge',['rr.p0336.t01.r017.c02'],'Сохранено словарное Капище; предложение Госпиталь и пояснение о молитве Шамана восстановлены возле таблицы.','вопрос сохранён')
    group([106],'Bladedancer',['rr.p0058.b001'],'Сохранена Дева клинков; предложение Танцор с клинками возвращено в примечание, без самостоятельного утверждения.','вопрос сохранён')
